update public.learning_paths
set
  title = 'World Literature',
  goal = 'World Literature',
  summary = 'Students study what world literature means, how texts circulate, and how comparison can be rigorous rather than superficial, treating translation as method, mediation, power, language texture, and interpretive problem. The sequence moves from ancient, sacred, medieval, and early modern literatures through Enlightenment and Romantic exchange, the global novel, modernism, postcolonial critique, diaspora, and intersectional reading. Later work covers contemporary publishing and canon formation, climate and speculative futures, digital circulation, and a comparative research project.',
  data = $wlitjson${"slug": "world-literature", "title": "World Literature", "description": "Students study what world literature means, how texts circulate, and how comparison can be rigorous rather than superficial, treating translation as method, mediation, power, language texture, and interpretive problem. The sequence moves from ancient, sacred, medieval, and early modern literatures through Enlightenment and Romantic exchange, the global novel, modernism, postcolonial critique, diaspora, and intersectional reading. Later work covers contemporary publishing and canon formation, climate and speculative futures, digital circulation, and a comparative research project.", "topics": [{"id": "d1013162-180e-4481-a470-cd47701a8a8a", "type": "topic", "title": "Defining World Literature and Comparative Method", "description": "What world literature means, how texts circulate, and how comparison can be rigorous rather than superficial.", "children": [{"id": "072bb34f-c979-4e2e-b323-5c0d9eceeb0d", "type": "subtopic", "title": "Key field terms", "children": [{"id": "6d9a1be1-4c12-4efc-a6b2-7b095f9e1a63", "type": "concept", "title": "world literature"}, {"id": "8f3ecb58-0043-402d-9f77-2a5f2327a77b", "type": "concept", "title": "global literature"}, {"id": "27c3b5e9-a0eb-46a8-98b6-3c69f0f8090c", "type": "concept", "title": "comparative literature"}, {"id": "327ef568-24ce-4cd5-b140-d979494d8099", "type": "concept", "title": "national literature"}, {"id": "cfa8764b-7f07-4eab-8f6c-cae064cfabca", "type": "concept", "title": "canon"}, {"id": "4fd94b9e-da5f-4954-af84-3c6ea48d085d", "type": "concept", "title": "circulation"}, {"id": "c7e83d10-f0d3-4e61-8d9e-bbd15c6c1c93", "type": "concept", "title": "reception"}, {"id": "192bf480-9072-4610-94af-80467b9a9d40", "type": "concept", "title": "translation"}, {"id": "62b43e38-4583-4e9d-a0d4-bd4b723c03d9", "type": "concept", "title": "scale"}], "description": "This subtopic gives students a vocabulary for the course's central categories and shows why none of them is neutral."}, {"id": "2329040d-96c2-48eb-b81d-1ce67cb5af25", "type": "subtopic", "title": "World-literature debates", "children": [{"id": "45d2a02a-0bcf-44d1-8559-82662a34e8bc", "type": "concept", "title": "Goethe and Weltliteratur"}, {"id": "26ebbdb0-ec7a-47c5-bed4-334bda52bf3d", "type": "concept", "title": "Damrosch and circulation"}, {"id": "17e559d8-fade-4fee-b02c-48f1d0fbb156", "type": "concept", "title": "Moretti and distant reading"}, {"id": "1dffd231-3ada-4aff-ad07-7659d2437716", "type": "concept", "title": "Casanova and literary world-systems"}, {"id": "7dff7502-02ef-406f-8340-ddc663b3c0f2", "type": "concept", "title": "Apter and critiques of untranslatability"}], "description": "Students learn that world literature can mean a canon, a reading method, a translation market, or a system of circulation."}, {"id": "b71838bf-fdc2-44de-b2e1-fe7fd7fe2349", "type": "subtopic", "title": "Responsible comparison", "children": [{"id": "2086bad4-badb-4882-b854-866db9262f67", "type": "concept", "title": "close reading before comparison"}, {"id": "edaff832-20ac-4f1d-a2d5-f90d8ac01c53", "type": "concept", "title": "historical specificity"}, {"id": "45c3903b-9432-47ce-b38d-1fab57308d6b", "type": "concept", "title": "formal comparison"}, {"id": "31d1c6e7-4e3f-4bb7-ae68-032d7e6d49b0", "type": "concept", "title": "thematic comparison"}, {"id": "7eb66d02-0b4f-487d-b72a-5b0888176906", "type": "concept", "title": "reception comparison"}, {"id": "303ec80c-ff16-4e2f-8f9c-46bd4f7df403", "type": "concept", "title": "limits of evidence"}], "description": "The goal is to compare across texts without flattening difference or using one culture as the silent norm."}]}, {"id": "f36983d2-1ba0-4b3c-ba42-6291e0896386", "type": "topic", "title": "Translation, Multilingualism, and Untranslatability", "description": "Translation as method, mediation, power, language texture, and interpretive problem.", "children": [{"id": "95488642-04de-4e45-a662-939d935ff609", "type": "subtopic", "title": "Translation as interpretation", "children": [{"id": "51efa882-226d-4676-bf75-caef4ab24717", "type": "concept", "title": "translator visibility"}, {"id": "1cc19fdd-96ef-4fd8-8a61-7e255d3f8267", "type": "concept", "title": "literal versus literary translation"}, {"id": "d9458a42-dc51-4918-bc3b-f77b0a4e41ee", "type": "concept", "title": "paratexts"}, {"id": "641f2865-a04d-41a7-816f-42b70383b015", "type": "concept", "title": "glossaries"}, {"id": "f0973b81-4e56-4835-b7e5-4320c9ea2d58", "type": "concept", "title": "domestication and foreignization"}, {"id": "a76d182e-ac4e-4dc2-b002-142b4fcca8c0", "type": "concept", "title": "relay translation"}], "description": "Translation is not a transparent transfer of meaning; it is a set of choices about sound, register, form, audience, and power."}, {"id": "7801a380-80d0-4bca-9f60-a6300af70bdd", "type": "subtopic", "title": "Multilingual literary worlds", "children": [{"id": "2d47cf5c-59a4-47c5-8708-43bae5ae3d1f", "type": "concept", "title": "code-switching"}, {"id": "ba82cee3-98ea-4044-af17-80300bb3e9ba", "type": "concept", "title": "diglossia"}, {"id": "a9375233-f7af-4f3e-9b98-e1db1befc155", "type": "concept", "title": "Creole and vernacular writing"}, {"id": "0c558f80-c056-42e8-8846-955d12760f3e", "type": "concept", "title": "self-translation"}, {"id": "da105048-ae84-450d-b799-4189b3c6be88", "type": "concept", "title": "colonial education"}, {"id": "435e7974-83f1-4759-aa25-b4b7b937b45a", "type": "concept", "title": "language hierarchy"}], "description": "World literature often emerges from contact zones where languages overlap, compete, and transform each other."}, {"id": "6c052556-11f0-4105-9d73-5c9d49c1160b", "type": "subtopic", "title": "Untranslatability and method", "children": [{"id": "984da2d0-40d2-471f-87b3-0e1081ce587b", "type": "concept", "title": "idiom"}, {"id": "d6e2dbd8-4c41-4e57-bce4-5a1d76598a24", "type": "concept", "title": "wordplay"}, {"id": "dad18f81-df72-4bec-a09d-c85515dd8b03", "type": "concept", "title": "sacred language"}, {"id": "890c784c-f28d-4a70-a44f-fe0a25cf4e5f", "type": "concept", "title": "oral performance"}, {"id": "51c2d12e-3d1d-4a6f-9809-538943cd5473", "type": "concept", "title": "cultural reference"}, {"id": "dd692860-b91c-4785-b301-e636e099b887", "type": "concept", "title": "sound pattern"}, {"id": "44002117-c135-4f93-84f8-8db935752dba", "type": "concept", "title": "translator notes"}], "description": "Students learn to notice what resists translation and how that resistance can become an interpretive clue."}]}, {"id": "ebd57f50-fa11-452c-ae34-46fc1f0390d5", "type": "topic", "title": "Ancient and Classical World Literatures", "description": "Early epics, lyric, drama, wisdom literature, narrative frames, and foundational literary forms across regions.", "children": [{"id": "b348d234-01bc-4840-aefb-a47b35403998", "type": "subtopic", "title": "Epic and heroic narrative", "children": [{"id": "297bd1bc-af89-424a-b940-0d0090983f81", "type": "concept", "title": "Gilgamesh"}, {"id": "c5018bf9-37a1-4b2c-9b88-b5c4e8962405", "type": "concept", "title": "Homeric epic"}, {"id": "6d6bcd8b-9b13-4c4a-b378-9d630434150c", "type": "concept", "title": "Mahabharata and Ramayana"}, {"id": "a894302d-d183-4a5c-a900-f4475a699744", "type": "concept", "title": "classical Chinese narrative"}, {"id": "bbc6c3d2-a0c7-4d15-bb3b-c73df70033ba", "type": "concept", "title": "oral-formulaic composition"}, {"id": "3437f3da-f83c-4df5-b7d8-a15cc77644b8", "type": "concept", "title": "journey and return"}], "description": "Epic traditions help students see how societies imagine heroism, violence, memory, cosmology, and political order."}, {"id": "3f217795-d71f-4418-bd0d-450d9e5943e6", "type": "subtopic", "title": "Lyric, drama, and performance", "children": [{"id": "1c3b1a25-52a5-4bf7-93ea-6eab7d8bd034", "type": "concept", "title": "Greek tragedy and comedy"}, {"id": "6c37da2a-191e-4ad0-909f-d17017e00526", "type": "concept", "title": "Sanskrit drama"}, {"id": "2de95e2b-366a-4f90-b82c-44ae558fd490", "type": "concept", "title": "classical Chinese poetry"}, {"id": "820c2848-f6a5-4cab-9d82-fb12f6f5d7b4", "type": "concept", "title": "Hebrew poetry"}, {"id": "b29a86a8-7840-4b7c-be24-526f8d237603", "type": "concept", "title": "chorus and ritual"}, {"id": "496bcdbe-ce31-48d9-920b-80d025618722", "type": "concept", "title": "speaker and audience"}], "description": "Students study how early literary forms shaped public speech, ritual, emotion, and civic imagination."}, {"id": "55092e3a-a337-41fd-88aa-50ff1d84a57c", "type": "subtopic", "title": "Ancient forms in later worlds", "children": [{"id": "eb819df9-c851-4eb8-93f6-e499c2dac51e", "type": "concept", "title": "reception history"}, {"id": "1e31dd79-9a5b-4400-8de1-a79ded21f561", "type": "concept", "title": "adaptation"}, {"id": "51510375-e6d7-41c1-939f-55ce1e9265ed", "type": "concept", "title": "canon formation"}, {"id": "fc2cc78f-41f3-4e26-b814-705ad5a098dd", "type": "concept", "title": "myth retelling"}, {"id": "16a9b6a7-0071-4898-8bde-1af917325fc6", "type": "concept", "title": "gendered revision"}, {"id": "a3950d78-46f8-4fe0-9c52-260ba1f08b29", "type": "concept", "title": "modern political uses of antiquity"}], "description": "Ancient texts continue to travel through translation, adaptation, colonial schooling, and modern rewriting."}]}, {"id": "e4c2b71d-8227-4509-891c-936b6ab1c379", "type": "topic", "title": "Sacred, Philosophical, and Wisdom Traditions", "description": "Scriptural, philosophical, didactic, and ethical texts as literary and cultural worlds.", "children": [{"id": "95a2db41-5aa1-4315-84bf-ff8a04e789e5", "type": "subtopic", "title": "Scripture as literature", "children": [{"id": "2c5b1ed8-d4dd-4d5b-bedc-7d36765db0f4", "type": "concept", "title": "creation narrative"}, {"id": "db0171d0-e5d7-4f41-ae7a-d5c29d269fda", "type": "concept", "title": "parable"}, {"id": "90c5fbea-aef4-42db-ba69-354466906a66", "type": "concept", "title": "prophecy"}, {"id": "9478b1d8-0774-4c04-b4f5-d330e8f04e3a", "type": "concept", "title": "psalm"}, {"id": "097a4d5d-915a-458f-9cc5-6b47c49bbca0", "type": "concept", "title": "sutra"}, {"id": "7b303fe5-1173-457c-8cc0-b13fedc7c4c4", "type": "concept", "title": "surah"}, {"id": "b0fd4840-5c77-4711-b018-465770fd1d17", "type": "concept", "title": "commentary tradition"}], "description": "Students read sacred texts with attention to narrative, poetry, genre, metaphor, voice, and interpretive tradition."}, {"id": "4059ed9b-9010-4e17-9ee1-7ccea8a8b03b", "type": "subtopic", "title": "Philosophical and ethical writing", "children": [{"id": "0fb5070c-05a5-4bda-a365-b02b6de63ce9", "type": "concept", "title": "dialogue"}, {"id": "c1623872-da09-4515-8568-c6542e0e45d8", "type": "concept", "title": "aphorism"}, {"id": "fa4e75fc-9c74-4715-8c29-90966062dc13", "type": "concept", "title": "didactic poetry"}, {"id": "70de808a-7a57-4de3-890a-3cd6af3c4783", "type": "concept", "title": "moral exemplum"}, {"id": "f77ad0b0-1c13-474f-a2c9-eefc1ae760ea", "type": "concept", "title": "virtue"}, {"id": "b86b8ea0-b452-4c8f-9772-83f5dc6b209a", "type": "concept", "title": "duty"}, {"id": "41240c19-ad2e-4455-a598-03f2a3017d8a", "type": "concept", "title": "suffering"}, {"id": "2ed2c621-d63b-4de9-8b3c-a99396dc7ed1", "type": "concept", "title": "justice"}], "description": "World literature includes texts that teach, argue, persuade, and imagine ways of living."}, {"id": "22bbcfce-b5e8-40f1-9833-ff839441a6e8", "type": "subtopic", "title": "Interpretive communities", "children": [{"id": "c046484b-76c5-4124-b751-d57684eb8b6a", "type": "concept", "title": "canon and commentary"}, {"id": "4e98ef2c-7ba8-44f6-b18d-ae14c6a87969", "type": "concept", "title": "oral recitation"}, {"id": "6efb58ae-0a5d-48e0-beef-941f4bd443f9", "type": "concept", "title": "translation debates"}, {"id": "422c62e9-e16e-46c4-9ae7-9db9af666a25", "type": "concept", "title": "sectarian interpretation"}, {"id": "33963379-1dc4-4e6f-b870-5fd35b08a9d5", "type": "concept", "title": "secular reading"}, {"id": "906936b2-b928-49c0-91bf-0d575d369de6", "type": "concept", "title": "comparative ethics"}], "description": "The same text changes meaning across ritual, translation, commentary, classroom, and political use."}]}, {"id": "ca2a2a16-c196-4501-a7b3-72fb9aae0bc8", "type": "topic", "title": "Medieval and Early Global Literary Networks", "description": "Story cycles, courts, travel writing, manuscript cultures, oral traditions, and cross-regional exchange.", "children": [{"id": "4762667b-164c-4f59-a777-6f9cf12bd7b9", "type": "subtopic", "title": "Manuscript, oral, and court cultures", "children": [{"id": "622d6f8d-4635-463a-b809-1ab1008a34e7", "type": "concept", "title": "manuscript copying"}, {"id": "6d9036f8-9f1c-4eeb-bca1-31a1e40c7fb4", "type": "concept", "title": "illumination"}, {"id": "695cbad1-5af5-43ab-8797-330604de4797", "type": "concept", "title": "bardic and troubadour traditions"}, {"id": "57335b20-6849-45a6-87fa-2f901465c4f9", "type": "concept", "title": "courtly love"}, {"id": "f83b395b-4c64-444e-b3cf-2aea1be67134", "type": "concept", "title": "patronage"}, {"id": "8c506738-36c2-430b-84d5-a134632ac243", "type": "concept", "title": "oral memory"}], "description": "This unit connects literary form to material transmission, patronage, performance, and elite/non-elite audiences."}, {"id": "0b317150-05e0-45bf-89e2-b4481a017c33", "type": "subtopic", "title": "Story cycles and frame narratives", "children": [{"id": "c5c774fb-d10d-44fd-9bd7-d39733045d33", "type": "concept", "title": "The Arabian Nights"}, {"id": "8b3f28ad-ea08-4599-a212-7b935270c817", "type": "concept", "title": "Panchatantra"}, {"id": "6b86057c-bd1c-48d1-99fd-e0c6367af03f", "type": "concept", "title": "Decameron"}, {"id": "06c56bca-e3b1-4168-8acb-b5859dd37f55", "type": "concept", "title": "Canterbury Tales"}, {"id": "06aa22b5-329d-4806-8ddc-450ecb6f62b9", "type": "concept", "title": "nested narrative"}, {"id": "aaec05a0-d2f0-4a78-a118-908718417818", "type": "concept", "title": "traveling motifs"}], "description": "Frame narratives show how stories move across languages, religions, empires, and trade routes."}, {"id": "c0f921bc-a552-422d-8b5d-90ac1732c2bb", "type": "subtopic", "title": "Travel, pilgrimage, and encounter", "children": [{"id": "06c6631b-8373-43b8-a8bc-bd36c15751e3", "type": "concept", "title": "pilgrimage"}, {"id": "31e0dc46-4c94-4db8-9d62-cb5af583d192", "type": "concept", "title": "travel writing"}, {"id": "4646857c-62ca-4dc6-85ea-b016f08632a9", "type": "concept", "title": "Silk Road"}, {"id": "96dbec95-365e-4576-8ee6-89e71e19fc5c", "type": "concept", "title": "Indian Ocean"}, {"id": "2d4aebf0-b207-4401-bcd8-b4d90da56b0a", "type": "concept", "title": "crusade and contact"}, {"id": "734e6cce-2ba3-41d7-b483-0ac36943a556", "type": "concept", "title": "marvels and ethnography"}], "description": "Medieval world literature records movement, curiosity, fear, commerce, mission, and cross-cultural imagination."}]}, {"id": "53db9f12-4755-47c7-ab4e-a4990f459288", "type": "topic", "title": "Early Modern Encounters, Empire, and Print", "description": "Encounter, conquest, print, humanism, performance, translation, and expanding literary worlds.", "children": [{"id": "374328ec-9673-49e9-b547-d2a11fe2b799", "type": "subtopic", "title": "Print and literary publics", "children": [{"id": "81d06a5f-364b-4dda-a070-175dd14628e6", "type": "concept", "title": "printing press"}, {"id": "d6aee07a-a621-434b-bb98-e716943ad406", "type": "concept", "title": "pamphlet culture"}, {"id": "5427d8e7-7ac9-4d1b-add5-54cfc1df9455", "type": "concept", "title": "book trade"}, {"id": "771c4ff6-6614-4854-a8df-c3bffabc744f", "type": "concept", "title": "censorship"}, {"id": "718db6fb-106e-4640-b36c-a43cff3290fd", "type": "concept", "title": "preface and dedication"}, {"id": "49a3e773-3774-46f6-b9db-fed403359654", "type": "concept", "title": "serial circulation"}], "description": "Print expanded readerships and altered authorship, authority, censorship, translation, and literary circulation."}, {"id": "6389e566-511f-4314-9916-835d964fe79e", "type": "subtopic", "title": "Encounter and conquest", "children": [{"id": "cf50f488-41fd-485f-8729-f4ee789c4353", "type": "concept", "title": "travel narrative"}, {"id": "c222142a-a521-4825-b347-85963d40b631", "type": "concept", "title": "colonial archive"}, {"id": "6dc374c8-cb28-4e94-8537-99be6b4011ff", "type": "concept", "title": "missionary writing"}, {"id": "b7f9f7c4-288c-4ddd-a022-85aa58474ec6", "type": "concept", "title": "captivity narrative"}, {"id": "afcf820a-29e0-4536-aee3-1d087e210336", "type": "concept", "title": "racial classification"}, {"id": "d0647e67-6bd5-4aba-b621-3251cf2614cd", "type": "concept", "title": "indigenous testimony"}], "description": "Students examine how literature registered empire, conquest, travel, conversion, slavery, and the making of the New World."}, {"id": "2ff63aba-5d2f-4340-930a-418fe9a1e9f5", "type": "subtopic", "title": "Drama, humanism, and global exchange", "children": [{"id": "563e7c76-2ce0-4bda-acca-b6ec40a80b3a", "type": "concept", "title": "Shakespeare and global adaptation"}, {"id": "5d498dd3-1abd-40e7-80b3-50bb4445934d", "type": "concept", "title": "Spanish Golden Age"}, {"id": "543ec624-a0e7-40a2-bf7f-86f740aa9e0c", "type": "concept", "title": "Ming/Qing literary worlds"}, {"id": "96476af1-8a9c-4d42-9266-7b79f56f5fbd", "type": "concept", "title": "Ottoman/Persianate forms"}, {"id": "3bcd75a0-e64c-43bf-ae58-b4a63407b86b", "type": "concept", "title": "humanism"}, {"id": "9a522ece-99ba-421e-89d2-b6c0ad466c56", "type": "concept", "title": "translation and imitation"}], "description": "Early modern texts are read as local works within increasingly global systems of trade, empire, and performance."}]}, {"id": "300bc5aa-8bc2-441f-80d2-a9e0d5fa9ce4", "type": "topic", "title": "Enlightenment, Romanticism, and the World Republic of Letters", "description": "Cosmopolitanism, nationalism, revolution, empire, sentiment, and global aesthetic exchange.", "children": [{"id": "25a1d966-264d-4278-a9d0-97cf79478a2e", "type": "subtopic", "title": "Cosmopolitanism and empire", "children": [{"id": "c1a0e560-8096-4338-a128-8a2039c2d190", "type": "concept", "title": "cosmopolitanism"}, {"id": "757b5c8d-b6eb-4fa0-a792-e860a72e77d6", "type": "concept", "title": "Orientalism"}, {"id": "0251979e-9358-4f6b-9230-8b1a5431859f", "type": "concept", "title": "abolition"}, {"id": "58fa2e7c-93ae-4ec2-bb23-161fa5c51d7d", "type": "concept", "title": "rights discourse"}, {"id": "51da9cf2-1f19-4533-92c1-2569caec58d8", "type": "concept", "title": "encyclopedism"}, {"id": "7c5c9827-fc7e-45c7-ad0f-1844bea4b937", "type": "concept", "title": "travel and classification"}], "description": "Students study how ideals of reason, universality, rights, and progress coexisted with slavery, colonialism, and exclusion."}, {"id": "601a9bf2-e9a8-407b-9d7a-79406a5577b1", "type": "subtopic", "title": "Revolution and sentiment", "children": [{"id": "fbda3053-1f8d-499b-b087-38389e3b3d9b", "type": "concept", "title": "French and Haitian revolutions"}, {"id": "46bcdbac-65c6-469c-a275-5b66d11fe455", "type": "concept", "title": "sentimental novel"}, {"id": "1f769e2b-31e4-465f-871d-780285dfd6e4", "type": "concept", "title": "slave narrative"}, {"id": "d3f211b2-c4a1-4883-9fba-73f2e2151ef4", "type": "concept", "title": "letters"}, {"id": "38e4f8c5-84ec-4ea6-afd8-7318aa8aa031", "type": "concept", "title": "revolutionary poetry"}, {"id": "878c4b0f-f189-45ea-96cb-96024b6cc78c", "type": "concept", "title": "public sphere"}], "description": "Literature helped imagine revolution, sympathy, citizenship, national feeling, and critique of authority."}, {"id": "df704ec2-d571-4cd3-afad-5c911d465fc9", "type": "subtopic", "title": "Romantic world-making", "children": [{"id": "c41c3bc7-b620-46b0-bcce-1c818c7600d4", "type": "concept", "title": "lyric subjectivity"}, {"id": "f079113a-e29a-4195-aec2-1f4e663da468", "type": "concept", "title": "folklore collection"}, {"id": "88ac1dd5-2b43-4d97-b4d5-1f8a6acc7e03", "type": "concept", "title": "sublime"}, {"id": "bb23d27a-747a-44f6-8871-48cc1e1b1105", "type": "concept", "title": "national epic"}, {"id": "a5e49d9a-6580-4b38-ae83-3808104a9bf1", "type": "concept", "title": "orientalist fantasy"}, {"id": "3b3b3c3d-8ce2-4cef-87cb-c67049093e23", "type": "concept", "title": "anti-imperial Romanticism"}], "description": "Romanticism is treated as a transnational movement shaped by nature, nation, folklore, translation, and empire."}]}, {"id": "8cad9230-d08c-40ed-9728-c3ed8e0d41d2", "type": "topic", "title": "The 19th-Century Global Novel and Realisms", "description": "The novel as a global form shaped by realism, colonial modernity, gender, class, nation, and capitalism.", "children": [{"id": "a85c567f-46d6-4f68-8b97-6e2401321aed", "type": "subtopic", "title": "The novel as global form", "children": [{"id": "bd5b6c34-63d1-4e8d-a844-53991567155c", "type": "concept", "title": "serial publication"}, {"id": "4aa98725-9022-4484-a5a6-5306d1b60d8b", "type": "concept", "title": "realism"}, {"id": "d9e06dd1-3bf0-44e0-a2f9-405b8124c235", "type": "concept", "title": "bildungsroman"}, {"id": "82b65e74-a9f6-45af-9d55-1ffde6470669", "type": "concept", "title": "family plot"}, {"id": "ad74b0fb-d757-429f-87ee-f13492ee4703", "type": "concept", "title": "omniscient narration"}, {"id": "f6053947-fbf4-43b0-90cf-85eabe50fe72", "type": "concept", "title": "free indirect discourse"}], "description": "The novel becomes a major technology for representing society, interiority, nation, class, and historical change."}, {"id": "8c156202-0035-448c-bee8-30800e782961", "type": "subtopic", "title": "Realism and social systems", "children": [{"id": "6bfc2e4c-9af5-4f97-b02b-89071b327802", "type": "concept", "title": "class mobility"}, {"id": "5bceb4a7-651f-4adc-be34-e9e390422029", "type": "concept", "title": "marriage plot"}, {"id": "0077364d-99a7-4a8e-8423-5ccd4fc91d68", "type": "concept", "title": "property"}, {"id": "b32c8a98-9774-4e9f-8da2-ee649f8badad", "type": "concept", "title": "industrialization"}, {"id": "992c338d-7a2f-4374-b37e-dd315f575670", "type": "concept", "title": "colonial modernity"}, {"id": "361e7c6a-8484-4493-a471-67aded9e0b18", "type": "concept", "title": "urbanization"}], "description": "Students learn how realist form maps money, labor, law, gender, domestic life, empire, and urban space."}, {"id": "b9bb0f90-691a-42be-9c51-087b090db8a7", "type": "subtopic", "title": "Beyond Europe", "children": [{"id": "5fe8b420-f052-40fc-9472-c1a91c011069", "type": "concept", "title": "Russian realism"}, {"id": "399a43af-aede-47b8-8df2-8d1b8357fd94", "type": "concept", "title": "Latin American fiction"}, {"id": "bd66430b-dcbc-4357-97af-2c566a89d70d", "type": "concept", "title": "Chinese late Qing fiction"}, {"id": "9998798c-9e4e-4891-bf91-3937db456293", "type": "concept", "title": "Indian novel"}, {"id": "185c6bf0-f589-410f-9072-3b8f0421d818", "type": "concept", "title": "Arabic nahda"}, {"id": "f4bc0462-d976-426f-81cb-3699c0ad82f2", "type": "concept", "title": "African mission-educated writing"}], "description": "The global novel develops through adaptation, translation, local traditions, colonial schools, and anti-colonial imagination."}]}, {"id": "13ba39c4-7cfb-453b-b94f-eb96b2a91466", "type": "topic", "title": "Modernism Globally", "description": "Modernism beyond Europe and the U.S., including little magazines, cities, war, empire, formal rupture, and multilingual experimentation.", "children": [{"id": "f89590ff-dc97-43cb-865b-9210fff731b3", "type": "subtopic", "title": "Modernist rupture", "children": [{"id": "dfb97028-aeb1-49e1-ba38-85f5a04f1c24", "type": "concept", "title": "fragmentation"}, {"id": "15f23196-e32a-4bc6-9858-1d4aee8befd5", "type": "concept", "title": "stream of consciousness"}, {"id": "95891c51-42ad-43ea-90c6-42ecde1a979d", "type": "concept", "title": "mythic method"}, {"id": "643e776e-f325-483d-a8f6-6ac63abbce24", "type": "concept", "title": "montage"}, {"id": "158e2743-4bb9-4967-8964-f35ac3947332", "type": "concept", "title": "interiority"}, {"id": "f8c01e92-c531-4130-83f1-7efbad3e4767", "type": "concept", "title": "formal difficulty"}], "description": "Modernism is framed as a world-scale response to war, empire, technology, urbanization, and changing consciousness."}, {"id": "6127d539-00fd-4799-a19e-3e837a5e0f02", "type": "subtopic", "title": "Little magazines and networks", "children": [{"id": "97a7528b-a795-4130-b52b-1aeae9793db3", "type": "concept", "title": "little magazine"}, {"id": "c325e324-c013-49fa-ae19-7b57a57afc14", "type": "concept", "title": "manifesto"}, {"id": "a5e77e1a-4b79-47ea-9db9-9d92535be327", "type": "concept", "title": "avant-garde"}, {"id": "41d47c30-1267-4e51-9333-91848de8a788", "type": "concept", "title": "Harlem Renaissance"}, {"id": "4bb16a8f-4a83-4382-9da8-f6b88a413d14", "type": "concept", "title": "Négritude"}, {"id": "981b9400-6c2a-4c77-9492-00b05e56d185", "type": "concept", "title": "Indian modernism"}, {"id": "40140e06-d3f3-4fd9-ab04-02a45d74e722", "type": "concept", "title": "Latin American vanguardia"}], "description": "Students learn how modernism spread through magazines, salons, presses, translation, migration, and colonial education."}, {"id": "972dbb62-a31a-4462-a538-126194236086", "type": "subtopic", "title": "Global modernist forms", "children": [{"id": "28aae792-edcc-4082-8e0b-a0c59e09fc3d", "type": "concept", "title": "city writing"}, {"id": "7f93aabf-5485-4938-82d6-749ae76d2cff", "type": "concept", "title": "anti-colonial modernism"}, {"id": "247ec39a-23bb-40fa-87a8-a7af5eef8769", "type": "concept", "title": "vernacular modernism"}, {"id": "f9dbe062-ba27-4136-a3d4-22b858d6a937", "type": "concept", "title": "gender and modernity"}, {"id": "8aa854aa-6d03-4f19-be02-c9c8b6738236", "type": "concept", "title": "diasporic modernism"}, {"id": "4652ce1c-89e3-441e-b44a-ece67ebd7a38", "type": "concept", "title": "world war and trauma"}], "description": "Modernism is not a single European style exported elsewhere; it is remade in many locations."}]}, {"id": "441fecb9-98e4-4c7e-9150-7dea524c2d16", "type": "topic", "title": "Postcolonial Theory, Decolonization, and World Literature", "description": "Reading literature after and against empire through language, nation, subalternity, hybridity, and decolonial critique.", "children": [{"id": "121cd660-dcbd-4b63-aae8-d58d22951847", "type": "subtopic", "title": "Empire and decolonization", "children": [{"id": "273c655d-3d22-4b67-acf3-40852f3c6d54", "type": "concept", "title": "colonial discourse"}, {"id": "c953f336-37a9-484e-abe6-92682f9636fc", "type": "concept", "title": "anticolonial nationalism"}, {"id": "41d6a16c-1412-4049-8402-dfa72eabd32a", "type": "concept", "title": "decolonization"}, {"id": "d0ff57b0-46b2-4e13-bd75-ee1c7c60f840", "type": "concept", "title": "neocolonialism"}, {"id": "44595a27-7050-49b7-9068-6ecbb3130665", "type": "concept", "title": "settler colonialism"}, {"id": "0a5b7f08-6097-4f73-865d-3b1db4a83be6", "type": "concept", "title": "imperial afterlives"}], "description": "Postcolonial theory gives students vocabulary for literature after and against empire."}, {"id": "a5b6f5f3-85f1-4f31-bba6-c162578ec34f", "type": "subtopic", "title": "Major theoretical conversations", "children": [{"id": "3ce53b3d-1467-41b5-aac5-8eb306fbb8b6", "type": "concept", "title": "Said"}, {"id": "de0d8ac0-281b-42ec-95f4-c9b43d0dfcef", "type": "concept", "title": "Spivak"}, {"id": "30eb4805-1789-4781-9629-e0848c2b48af", "type": "concept", "title": "Bhabha"}, {"id": "6b5fa621-72cf-4454-8f07-7c1d09748210", "type": "concept", "title": "Fanon"}, {"id": "4ec7bf2e-8106-44c6-8722-bb27b069eef4", "type": "concept", "title": "Ngugi"}, {"id": "4427e183-f6c1-4d81-be52-97619790cc9a", "type": "concept", "title": "subaltern studies"}, {"id": "c8c2e11e-8d39-4f88-bd56-dfaf37de28c1", "type": "concept", "title": "hybridity"}, {"id": "c502eb2a-ce7a-4ec9-b713-e17c995767ed", "type": "concept", "title": "mimicry"}], "description": "Students connect literature to the field's major concepts and debates."}, {"id": "c8e90551-d833-4fa8-a836-420bb5252cb8", "type": "subtopic", "title": "Reading postcolonially", "children": [{"id": "c5e5a0d9-3a70-430d-aac7-b2b0aff39d60", "type": "concept", "title": "narrative voice"}, {"id": "6e908f26-04b5-48d1-a4b7-11acfb1649e3", "type": "concept", "title": "allegory"}, {"id": "2f8c1ce0-b9b6-49c9-b5b8-c23d0a2f1ada", "type": "concept", "title": "code-switching"}, {"id": "ef19d6b4-2d46-4026-bfa5-e1b7003d6cf3", "type": "concept", "title": "unreliable narration"}, {"id": "181208d9-3066-454f-a817-864148bc9215", "type": "concept", "title": "archival silence"}, {"id": "43b7286b-5235-4fc7-8442-e7c9dd7aa512", "type": "concept", "title": "nation and gender"}, {"id": "5b55c8ff-57d9-4add-83c8-f9c293d4d290", "type": "concept", "title": "language politics"}], "description": "Theory becomes useful when students connect it to formal choices in poems, novels, drama, memoir, and essays."}]}, {"id": "2095288a-f0d2-4aa0-a7e9-47bf7b8dec3c", "type": "topic", "title": "Diaspora, Migration, Refugee Writing, and Transnational Identity", "description": "Literatures of mobility, exile, migration, border regimes, home, memory, and belonging.", "children": [{"id": "941f03d1-1203-4b49-a1fe-d7be9c60072c", "type": "subtopic", "title": "Mobility and displacement", "children": [{"id": "96b95b74-97a9-474a-b9d0-93b047fc03e6", "type": "concept", "title": "exile"}, {"id": "a87c6cc3-11ff-4c42-a152-4489eb03fdfc", "type": "concept", "title": "refugeehood"}, {"id": "61d120ce-837a-4217-ad6c-b7a9fa7ecb0e", "type": "concept", "title": "asylum"}, {"id": "4a4f0a1b-ddba-4701-a430-3ceebf0b3ca2", "type": "concept", "title": "labor migration"}, {"id": "66e47ad2-fff3-4786-a960-fff278428f53", "type": "concept", "title": "border regimes"}, {"id": "18dd77f2-3a57-4932-b15a-1a46d93a6eb9", "type": "concept", "title": "statelessness"}, {"id": "432ec8cb-0601-4085-8c9a-9115071fdee0", "type": "concept", "title": "return"}], "descript